"""
OmniAgent Integration Catalog (v3 -- full n8n coverage)
=========================================================
Generated from ALL 443 credential types in n8n's source (packages/nodes-base/credentials/,
packages/@n8n/nodes-langchain/credentials/), grouped into 386 real service families
(11 abstract/generic base types -- httpBasicAuth, oAuth2Api, googleOAuth2Api, etc. -- excluded,
since they represent auth mechanisms, not standalone products). No longer restricted to the
original 89-service whitelist -- any n8n-supported service is connectable.

Categories are auto-inferred via keyword matching and may be imprecise for niche/long-tail
services (category="Other" is a real, expected bucket -- mostly security/infra tools outside
typical Corporate/Education/Finance workflows). Safe to hand-correct category/display_name;
do NOT hand-edit auth_type/fields/oauth -- regenerate from the n8n credential registry instead.

connection_pattern per auth_option:
  1 = Text fields only        -> POST directly to n8n Credentials API
  2 = OAuth2                  -> user supplies own client_id/secret, OmniAgent runs consent flow
  4 = OAuth2 + extra fields   -> pattern 2 + non-secret extras (server URL, environment, etc.)
(Pattern 3, MCP OAuth, is not service-specific and lives in mcp_catalog.py, not here.)

Legacy OAuth1-only credential types (no OAuth2 alternative) are excluded from auth_options --
out of scope, since none of our 4 connection patterns support OAuth1's signing mechanism.
"""

